// Regenerates supabase/seed.sql from the menu in frontend/src/data/menu.js
//   node scripts/gen-seed.mjs
import { writeFileSync } from 'node:fs'
import { MENU } from '../frontend/src/data/menu.js'

const q = (v) => (v == null ? 'null' : `'${String(v).replace(/'/g, "''")}'`)
const j = (v) => (v == null ? 'null' : `${q(JSON.stringify(v))}::jsonb`)

const out = [
  '-- Generated by scripts/gen-seed.mjs. Safe to re-run (clears and reloads the menu).',
  'begin;',
  'delete from public.menu_items;',
  'delete from public.menu_sections;',
  '',
]
let sort = 0
for (const [audience, sections] of Object.entries(MENU)) {
  for (const s of sections) {
    out.push(
      `insert into public.menu_sections (id, audience, title, icon, cols, sort) values (${q(s.id)}, ${q(audience)}, ${q(s.title)}, ${q(s.icon)}, ${j(s.cols)}, ${sort++});`,
    )
    const rows = s.items.map((it, i) => `  (${q(s.id)}, ${q(it.name)}, ${q(it.note)}, ${j(it.prices)}, ${i})`)
    out.push('insert into public.menu_items (section_id, name, note, prices, sort) values', rows.join(',\n') + ';', '')
  }
}
out.push('commit;', '')
writeFileSync(new URL('../supabase/seed.sql', import.meta.url), out.join('\n'))
console.log('wrote supabase/seed.sql')
